SELECT mi1.info, pi.info, COUNT(*)
FROM title as t, kind_type as kt, movie_info as mi1, info_type as it1, cast_info as ci, role_type as rt, name as n, info_type as it2, person_info as pi, non_leaf_300
WHERE (pi.info ILIKE '%20%') AND (kt.kind IN ('episode','movie','tv mini series','tv movie','video game','video movie')) AND it2.id = pi.info_type_id AND n.id = non_leaf_300.ci_person_id AND it1.id = non_leaf_300.mi1_info_type_id AND (it1.id IN ('107')) AND n.id = pi.person_id AND (it2.id IN ('21')) AND (mi1.info ILIKE '%20%') AND (rt.role IN ('actress','composer','costume designer','director','editor','guest','miscellaneous crew','producer','production designer','writer'));